bool find_word(const char*const*g,size_t rows,const char*w,coordinate*s,coordinate*e){size_t n=strlen(w);if(!n)return false;for(size_t r=0;r<rows;r++)for(size_t c=0;c<strlen(g[r]);c++)for(int dr=-1;dr<=1;dr++)for(int dc=-1;dc<=1;dc++){if(!dr&&!dc)continue;size_t k;for(k=0;k<n;k++){long rr=(long)r+(long)k*dr,cc=(long)c+(long)k*dc;if(rr<0||cc<0||(size_t)rr>=rows||(size_t)cc>=strlen(g[rr])||g[rr][cc]!=w[k])break;}if(k==n){s->row=r;s->column=c;e->row=(size_t)((long)r+(long)(n-1)*dr);e->column=(size_t)((long)c+(long)(n-1)*dc);return true;}}return false;}